Colleges by county
Pick the counties and college levels to compare. USHE covers public institutions only and has no level split, so its bar always shows all levels. The age band counts persons aged 18-24 whatever the level, as a sanity bound.

Show code
viewof selectedCounties = Inputs.select(countyOrder, {
  label: "Counties",
  multiple: 5,
  value: countyOrder,
  format: c =&gt; countyName[c]
})

viewof selectedCollegeLevels = Inputs.select(["Undergraduate", "Graduate"], {
  label: "College level",
  multiple: 2,
  value: ["Undergraduate", "Graduate"]
})

viewof collegeIncludePrivate = Inputs.checkbox(["Include private institutions"], {
  label: "Institutions",
  value: ["Include private institutions"]
})

viewof splitByCounty = Inputs.checkbox(["Split by county"], {
  label: "Chart",
  value: ["Split by county"]
})





























Show code
selectedCountySplit = splitByCounty.length &gt; 0;
includePrivate = collegeIncludePrivate.length &gt; 0;
ipedsLabel = includePrivate ? "IPEDS, all institutions" : "IPEDS, public only";
ipedsInScope = d =&gt; includePrivate || d.Control === "Public";
































Show code
collegeRows = {
  const out = [];
  for (const c of selectedCounties) {
    const ipeds = d3.sum(
      realCollegeLevel.filter(d =&gt; d.COUNTYFP === c && selectedCollegeLevels.includes(d.Level) && ipedsInScope(d)),
      d =&gt; d.nces_enrollment
    );
    const ushe = realCountyTotals.find(d =&gt; d.COUNTYFP === c)?.ushe_enrollment ?? 0;
    const syn = synthCollege.find(d =&gt; d.COUNTYFP === c) ?? {undergraduate: 0, graduate: 0, age_18_24: 0};
    const synEnrolled =
      (selectedCollegeLevels.includes("Undergraduate") ? syn.undergraduate : 0) +
      (selectedCollegeLevels.includes("Graduate") ? syn.graduate : 0);
    out.push({county: countyName[c], source: "USHE (all levels)", students: ushe});
    out.push({county: countyName[c], source: ipedsLabel, students: ipeds});
    out.push({county: countyName[c], source: "Synthetic enrolled", students: synEnrolled});
    out.push({county: countyName[c], source: "Synthetic age 18-24", students: syn.age_18_24});
  }
  if (selectedCountySplit) return out;
  // Split off: add the selected counties into one total per source
  return d3.rollups(out, v =&gt; d3.sum(v, d =&gt; d.students), d =&gt; d.source)
    .map(([source, students]) =&gt; ({county: "Total", source, students}));
}

